(5031, 'mw_polylang_strings_theme_twentysixteen_data', 'a:2:{s:4:\"name\";s:14:\"Twenty Sixteen\";s:7:\"strings\";a:48:{i:0;s:17:\"Base Color Scheme\";i:1;s:21:\"Page Background Color\";i:2;s:10:\"Link Color\";i:3;s:15:\"Main Text Color\";i:4;s:20:\"Secondary Text Color\";i:5;s:7:\"Default\";i:6;s:4:\"Dark\";i:7;s:4:\"Gray\";i:8;s:3:\"Red\";i:9;s:6:\"Yellow\";i:10;s:61:\"Leave a comment<span class=\"screen-reader-text\"> on %s</span>\";i:11;s:61:\"Continue reading<span class=\"screen-reader-text\"> \"%s\"</span>\";i:12;s:113:\"Twenty Sixteen requires at least WordPress version 4.4. You are running version %s. Please upgrade and try again.\";i:13;s:20:\"Comments are closed.\";i:14;s:6:\"Pages:\";i:15;s:4:\"Page\";i:16;s:49:\"Edit<span class=\"screen-reader-text\"> \"%s\"</span>\";i:17;s:13:\"Nothing Found\";i:18;s:70:\"Ready to publish your first post? <a href=\"%1$s\">Get started here</a>.\";i:19;s:92:\"Sorry, but nothing matched your search terms. Please try again with some different keywords.\";i:20;s:87:\"It seems we can&rsquo;t find what you&rsquo;re looking for. Perhaps searching can help.\";i:21;s:7:\"Author:\";i:22;s:20:\"View all posts by %s\";i:23;s:8:\"Featured\";i:24;s:22:\"Search Results for: %s\";i:25;s:13:\"Previous page\";i:26;s:9:\"Next page\";i:27;s:12:\"Primary Menu\";i:28;s:17:\"Social Links Menu\";i:29;s:7:\"Sidebar\";i:30;s:43:\"Add widgets here to appear in your sidebar.\";i:31;s:16:\"Content Bottom 1\";i:32;s:56:\"Appears at the bottom of the content on posts and pages.\";i:33;s:16:\"Content Bottom 2\";i:34;s:17:\"expand child menu\";i:35;s:19:\"collapse child menu\";i:36;s:22:\"https://wordpress.org/\";i:37;s:21:\"Proudly powered by %s\";i:38;s:14:\"Previous Image\";i:39;s:10:\"Next Image\";i:40;s:15:\"Skip to content\";i:41;s:4:\"Menu\";i:42;s:37:\"Oops! That page can&rsquo;t be found.\";i:43;s:69:\"It looks like nothing was found at this location. Maybe try a search?\";i:44;s:4:\"Next\";i:45;s:10:\"Next post:\";i:46;s:8:\"Previous\";i:47;s: