(4860, 389, 'additional_information', ''),
(4861, 389, '_additional_information', 'field_5b179f01e7fc5'),
(4862, 389, 'additional_information_banners_blok_1_title', 'Правила проживания'),
(4863, 389, '_additional_information_banners_blok_1_title', 'field_5b17c520b33b2'),
