INSERT INTO `wp_a_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(8350, 678, 'additional_information_banners_blok_2_descr', '<p style=\"text-align: left;\"><strong>Постельное бельё</strong>\r\nБесплатно мы предоставляем по одному комплекту белья на каждую\r\nкровать и одно полотенце на человека. Стоимость использования каждого\r\nдополнительного комплекта белья 200 руб и полотенца 100 руб.\r\n<strong>Коллекция фильмов</strong>\r\nВ каждой квартире есть флэшка с бесплатными фильмами, на которой около 20 интересных кино разных жанров. Залог за флешку 700 руб, он возвращается вам при выезде.\r\n<strong>Беспроводной интернет и кабельное телевидение</strong>\r\nВ каждой квартире есть памятка с паролем от Wi-Fi.</p>'),
(8351, 678, '_additional_information_banners_blok_2_descr', 'field_5b17c573b33b8'),
(8352, 678, 'additional_information_banners_blok_2', ''),
(8353, 678, '_additional_information_banners_blok_2', 'field_5b17c573b33b5'),
(8354, 678, 'additional_information_banners_blok_3_title', 'Платные услуги'),
(8355, 678, '_additional_information_banners_blok_3_title', 'field_5b17c583b33ba'),
(8356, 678, 'additional_information_banners_blok_3_img', '304'),
(8357, 678, '_additional_information_banners_blok_3_img', 'field_5b17c583b33bb'),
(8358, 678, 'additional_information_banners_blok_3_descr', '<strong>Аренда игровой приставки</strong>\r\nАренда приставки X-box 360 или Sony Play Station с установленными\r\nиграми и двумя джойстиками. Стоимость проката 1000 руб за первые\r\nсутки и всего 100 руб за каждые последующие.\r\n<strong>Комплект нового постельного белья</strong>\r\nДля вас мы можем купить новый комплект постельного белья из IKEA размером 2 м * 2 м. Бельё дествительно будет новое, в упаковке.Стоимость такой услуги всего 500 руб на весь срок проживания.Например, если вы планируете жить две недели, то получаетсявсего по 35 руб в день.'),
(8359, 678, '_additional_information_banners_blok_3_descr', 'field_5b17c583b33bc'),
(8360, 678, 'additional_information_banners_blok_3', ''),
(8361, 678, '_additional_information_banners_blok_3', 'field_5b17c583b33b9'),
