(9491, 753, '_additional_information', 'field_5b179f01e7fc5'),
(9492, 753, 'additional_information_banners_blok_1_title', 'Правила проживания'),
(9493, 753, '_additional_information_banners_blok_1_title', 'field_5b17c520b33b2'),
