(11726, 815, 'additional_information_banners_blok_1_title', 'Accommodation Rules'),
(11727, 815, 'additional_information_banners_blok_1_img', '303'),
(11728, 815, 'additional_information_banners_blok_1_descr', '<strong>Allowed</strong>\r\n<ul>\r\n 	<li>spend time at home with family</li>\r\n 	<li>cook food on the stove and in the oven</li>\r\n 	<li>washing clothes in a washing machine</li>\r\n 	<li>smoke on the balcony with the door closed</li>\r\n 	<li>use internet and cable tv</li>\r\n</ul>\r\n<strong>Prohibited</strong>\r\n<ul>\r\n 	<li>parties at home</li>\r\n 	<li>celebrate holidays</li>\r\n 	<li>smoking in the apartment</li>\r\n 	<li>litter in the apartment</li>\r\n 	<li>make noise in the apartment</li>\r\n 	<li>carelessly treat property in an apartment</li>\r\n 	<li>the presence of more people than in the contract</li>\r\n</ul>'),
(11793, 815, '_additional_information_banners_blok_1_descr', 'field_5b17c552b33b4'),
(11794, 815, '_additional_information_banners_blok_1', 'field_5b17c480b33b1'),
(11795, 815, '_additional_information_banners_blok_2_title', 'field_5b17c573b33b6'),
(11729, 815, 'additional_information_banners_blok_1', ''),
(11730, 815, 'additional_information_banners_blok_2_title', 'Free services'),
(11731, 815, 'additional_information_banners_blok_2_img', '305'),
(11732, 815, 'additional_information_banners_blok_2_descr', '<p style=\"text-align: left;\"><strong>Linens</strong>\r\nWe suggest one bed linen to one bed. The coast of using extra linens is 200 rubles and towel 100 rubles.\r\n<strong>Movie collection</strong>\r\nEach apartment has a flash drive with free movies, on which about 20 interesting movies of different genres. For the flash drive we take 700 rub. deposit and return it when you check-out.\r\n<strong>Wi-fi internet and cable TV</strong>\r\nEach apartment has a memo with a password of Wi-Fi.</p>'),
(11797, 815, '_additional_information_banners_blok_2_descr', 'field_5b17c573b33b8'),
(11798, 815, '_additional_information_banners_blok_2', 'field_5b17c573b33b5'),
(11799, 815, '_additional_information_banners_blok_3_title', 'field_5b17c583b33ba'),
(11800, 815, '_additional_information_banners_blok_3_img', 'field_5b17c583b33bb'),
